-- PRODUCTION PREPARATION ONLY; DO NOT EXECUTE BEFORE APPROVAL.
-- Confirm Dashboard URL project/rtgqyctqjfoercdymssd (snow-condition-app).
-- SQL session metadata alone cannot prove the Supabase Project reference.
-- Applies only the reviewed content safety migration. No accounts/posts are deleted.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
DO $apply$
DECLARE source_sql text:=convert_from(decode('','base64'),'UTF8');
 before_posts text;after_posts text;before_limits text;after_limits text;applied boolean:=false;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'UNEXPECTED_MIGRATION_ROLE'; END IF;
 IF encode(sha256(convert_to(source_sql,'UTF8')),'hex')<>'96affa0cd7bb959e40bf41b33bad8cd07a78fb3d7c52b1d2036af1f0c480d299' THEN RAISE EXCEPTION 'SOURCE_SHA256_MISMATCH'; END IF;
 LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE snownow_private.snow_posts,snownow_private.post_limits IN SHARE ROW EXCLUSIVE MODE;
 SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY id)::text,'[]')) INTO before_posts FROM snownow_private.snow_posts p;
 SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY user_id)::text,'[]')) INTO before_limits FROM snownow_private.post_limits p;
 IF EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261124000200') THEN
  IF NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261124000200' AND name='user_content_safety' AND statements=ARRAY[source_sql]) THEN RAISE EXCEPTION 'CONTENT_SAFETY_HISTORY_MISMATCH'; END IF;
 ELSE
  EXECUTE source_sql;
  INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20261124000200','user_content_safety',ARRAY[source_sql]);
  applied:=true;
 END IF;
 IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='snownow_private' AND c.relname IN ('user_blocks','post_reports','hidden_posts','suspended_authors','content_filter_terms') AND c.relkind='r' AND c.relrowsecurity)<>5
 OR NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid='snownow_private.snow_posts'::regclass AND polname='posts_safety_read' AND NOT polpermissive)
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='snownow_private.snow_posts'::regclass AND tgname='post_content_safety' AND tgenabled<>'D') THEN RAISE EXCEPTION 'CONTENT_SAFETY_SCHEMA_MISMATCH'; END IF;
 SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY id)::text,'[]')) INTO after_posts FROM snownow_private.snow_posts p;
 SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY user_id)::text,'[]')) INTO after_limits FROM snownow_private.post_limits p;
 IF before_posts IS DISTINCT FROM after_posts OR before_limits IS DISTINCT FROM after_limits THEN RAISE EXCEPTION 'CONTENT_SAFETY_EXISTING_DATA_CHANGED'; END IF;
 PERFORM set_config('snowviking.content_safety_result',jsonb_build_object('status',CASE WHEN applied THEN 'CONTENT_SAFETY_APPLIED_AND_DATA_PRESERVED' ELSE 'CONTENT_SAFETY_ALREADY_APPLIED' END,'version','20261124000200','posts_exact_match',true,'post_limits_exact_match',true,'rls_tables',5,'source_sha256','96affa0cd7bb959e40bf41b33bad8cd07a78fb3d7c52b1d2036af1f0c480d299')::text,true);
END;
$apply$;
SELECT current_setting('snowviking.content_safety_result')::jsonb AS result;
COMMIT;
